function b64ToUtf8(b64) {
  const binStr = atob(b64);
  const bytes = new Uint8Array(binStr.length);
  for (let i = 0; i < binStr.length; i++) {
    bytes[i] = binStr.charCodeAt(i);
  }
  return new TextDecoder("utf-8").decode(bytes);
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    
    if (url.pathname === "/manifest.json") {
      return new Response(`{"name":"HARZ Browser","short_name":"Browser","description":"Fast, Private browser for the HARZ Ecosystem","start_url":"/","display":"standalone","background_color":"#f0f2f5","theme_color":"#f0f2f5","orientation":"portrait","icons":[{"src":"/icon.svg","sizes":"any","type":"image/svg+xml","purpose":"any maskable"}]}`, {
        headers: { "Content-Type": "application/manifest+json", "Cache-Control": "public, max-age=3600" }
      });
    }
    if (url.pathname === "/sw.js") {
      return new Response(b64ToUtf8(""), {
        headers: { "Content-Type": "application/javascript", "Cache-Control": "no-cache, must-revalidate" }
      });
    }
    if (url.pathname === "/icon.svg" || url.pathname === "/icon.png") {
      return new Response(`<svg xmlns="http://www.w3.org/2000/svg" width="192" height="192" viewBox="0 0 192 192"><rect width="192" height="192" rx="40" fill="#f0f2f5"/><circle cx="96" cy="96" r="50" fill="none" stroke="#1877f2" stroke-width="6"/><path d="M46 96h100M96 46v100M60 60c20 20 20 52 0 72M132 60c-20 20-20 52 0 72" stroke="#1877f2" stroke-width="4" fill="none"/></svg>`, {
        headers: { "Content-Type": "image/svg+xml", "Cache-Control": "public, max-age=86400" }
      });
    }

    if (url.pathname === "/doc-data") {
      const CORS = { "Access-Control-Allow-Origin": "*", "Content-Type": "application/json; charset=utf-8" };
      const sid = url.searchParams.get("sid"), id = url.searchParams.get("id"), hash = url.searchParams.get("hash");
      if (!sid && !id && !hash) return Response.json({ ok: false, error: "sid, id or hash required" }, { status: 400, headers: CORS });
      let ref = {}, partial = null, target = null, sdUrl = null;
      if (sid) {
        ref = { sid: String(sid) };
        try {
          const r = await env.B_HARZ_SEARCH.fetch(new Request("https://harz-search.harz.workers.dev/document/" + encodeURIComponent(sid), { headers: { "User-Agent": "harz-browser-doc/1" } }));
          if (r.status === 404) return Response.json({ ok: false, error: "doc not found" }, { status: 404, headers: CORS });
          if (r.ok) {
            const sd = await r.json();
            partial = { title: sd.title, url: sd.url, domain: sd.domain, source: sd.source, snippet: sd.text || "" };
            if (sd.content_hash) target = { hash: sd.content_hash };
            if (sd.url) sdUrl = sd.url;
          }
        } catch (e) {}
      } else if (id) {
        if (!/^\d+$/.test(id)) return Response.json({ ok: false, error: "bad id" }, { status: 400, headers: CORS });
        target = { id: id }; ref = { id: String(id) };
      } else if (hash) {
        target = { hash: hash }; ref = { hash: String(hash) };
      }
      const tries = [];
      if (target && target.id) tries.push("id=" + encodeURIComponent(target.id));
      else if (target && target.hash) tries.push("hash=" + encodeURIComponent(target.hash));
      if (sdUrl) tries.push("url=" + encodeURIComponent(sdUrl));
      for (const qs of tries) {
        if (!env.WAVE_KEY) break;
        try {
          const cr = await env.B_HARZ_CORPUS.fetch(new Request("https://harz-million-corpus.harz.workers.dev/api/doc?" + qs + "&key=" + encodeURIComponent(env.WAVE_KEY), { headers: { "User-Agent": "harz-browser-doc/1" } }));
          if (cr.ok) {
            const cj = await cr.json();
            if (cj.ok && cj.doc) {
              const useRef = (qs.startsWith("hash=") || qs.startsWith("id=")) && ref && Object.keys(ref).length ? ref : { hash: cj.doc.content_hash };
              return Response.json({ ok: true, full: true, ref: useRef, doc: { id: cj.doc.id, content_hash: cj.doc.content_hash, url: cj.doc.url, title: cj.doc.title, domain: cj.doc.domain, source: cj.doc.source, language: cj.doc.language, fetched_at: cj.doc.fetched_at, size: cj.doc.size, text_len: cj.doc.text_len, text: cj.doc.text } }, { headers: CORS });
            }
          }
        } catch (e) {}
      }
      if (partial) return Response.json({ ok: true, full: false, ref: ref, doc: { title: partial.title, url: partial.url, domain: partial.domain, source: partial.source, snippet: partial.snippet, snippet_len: (partial.snippet || "").length } }, { headers: CORS });
      return Response.json({ ok: false, error: "doc not found" }, { status: 404, headers: CORS });
    }
    if (url.pathname === "/doc") {
      const H = `<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#f0f2f5"><title>HARZ Reader</title><style>
body{font-family:-apple-system,system-ui,sans-serif;background:#f0f2f5;color:#1c1e21;margin:0;padding:0}
.top{position:sticky;top:0;background:#fff;border-bottom:1px solid #dadde1;padding:10px 14px;display:flex;align-items:center;gap:8px;flex-wrap:wrap;z-index:5}
.top h1{font-size:15px;margin:0;flex:1;min-width:120px;font-weight:600}
.badge{display:inline-block;border-radius:10px;padding:2px 10px;font-size:11px;font-weight:700}
.b-LIVE{background:#e7f6e7;color:#1a7a1a}.b-OFFLINE{background:#fff0e0;color:#a05a00}.b-CACHED{background:#e3edff;color:#1a4a8a}.b-PREVIEW{background:#f0e6fa;color:#5a2a8a}.b-MISSING{background:#fdecea;color:#8a1a1a}.b-NO-NET{background:#eee;color:#555}
.meta{font-size:12px;color:#65676b;padding:8px 14px;background:#fff;border-bottom:1px solid #dadde1}
.art{max-width:720px;margin:0 auto;padding:16px}
.art p{font-size:16px;line-height:1.65;margin:0 0 14px}
.note{font-size:12px;color:#65676b;margin:10px 0}
.btn{display:inline-block;background:#1877f2;color:#fff;border-radius:8px;padding:8px 16px;font-size:13px;text-decoration:none;margin-top:8px}
.net{position:fixed;bottom:0;left:0;right:0;text-align:center;font-size:11px;padding:4px;background:#eef2f0;color:#334;z-index:9}
</style></head><body>
<div class="top"><h1 id="t">Loading document...</h1><span id="badge" class="badge b-CACHED">...</span></div>
<div class="meta" id="meta"></div>
<div class="art" id="body"></div>
<div class="net" id="net">checking network...</div>
<script>
(function(){
var qs=new URLSearchParams(location.search);
var sid=qs.get('sid'),id=qs.get('id'),hash=qs.get('hash');
var refKey=sid?'sid:'+sid:(id?'id:'+id:'hash:'+hash);
var dbp=new Promise(function(res,rej){var o=indexedDB.open('harz-docs',1);
o.onupgradeneeded=function(){o.result.createObjectStore('docs')};
o.onsuccess=function(){res(o.result)};o.onerror=function(){rej(o.error)}});
function tx(mode,fn){return dbp.then(function(db){return new Promise(function(res,rej){
var t=db.transaction('docs',mode),r=fn(t.objectStore('docs'));
r.onsuccess=function(){res(r.result)};r.onerror=function(){rej(r.error)}})});}
function getCache(k){return tx('readonly',function(s){return s.get(k)}).catch(function(){return null})}
function putCache(k,v){return tx('readwrite',function(s){return s.put(v,k)}).catch(function(){})}
function esc(s){return String(s==null?'':s).replace(/[&<>"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]})}
function setBadge(l){var b=document.getElementById('badge');b.textContent=l;b.className='badge b-'+l;}
function netBar(on){document.getElementById('net').textContent=on?'\u25CF ONLINE \u00B7 '+new Date().toLocaleTimeString():'\u25CF OFFLINE \u00B7 reading stored copy';document.getElementById('net').textContent+=' \u00B7 SW '+(navigator.serviceWorker&&navigator.serviceWorker.controller?'on':'pending');document.getElementById('net').style.background=on?'#eef2f0':'#fdeaea';}
function render(j,label,savedAt){
  var d=j.doc||{};
  document.title='HARZ Reader \u2014 '+((d.title||'document').slice(0,60));
  document.getElementById('t').textContent=(d.title||'Untitled document').slice(0,90);
  setBadge(label);
  var meta=[];
  if(d.domain)meta.push(d.domain);
  if(d.source)meta.push(d.source);
  if(d.text_len)meta.push(d.text_len.toLocaleString()+' chars');
  else if(d.snippet_len)meta.push('preview '+d.snippet_len+' chars');
  if(d.size)meta.push((d.size/1024).toFixed(1)+' KB');
  if(savedAt)meta.push('saved on device '+new Date(savedAt).toLocaleString());
  document.getElementById('meta').textContent=meta.join(' \u00B7 ');
  var body=document.getElementById('body');
  if(label==='PREVIEW'){
    body.innerHTML='<div class="note">This document is not in the corpus yet \u2014 showing the 2,000-character search preview. Full offline reading becomes available once the page is ingested.</div>'
      +(d.url?'<a class="btn" href="'+esc(d.url)+'" target="_blank" rel="noopener">Open original (needs internet)</a><div style="height:14px"></div>':'')
      +String(d.snippet||'').split(/\\n{2,}/).map(function(p){return '<p>'+esc(p)+'</p>'}).join('');
  } else {
    var txt=String(d.text||'');var shown=txt;
    var limit=200000;var cutNote='';
    if(txt.length>limit){shown=txt.slice(0,limit);cutNote='<div class="note">Showing first '+limit.toLocaleString()+' chars for display; the complete '+txt.length.toLocaleString()+' chars are stored on this device.</div>';}
    body.innerHTML=cutNote+shown.split(/\\n{2,}/).map(function(p){return '<p>'+esc(p)+'</p>'}).join('');
  }
}
function renderEmpty(){
  document.getElementById('t').textContent='Document not found';
  setBadge('MISSING');
  document.getElementById('meta').textContent='No stored copy and no live copy available.';
  document.getElementById('body').innerHTML='<p>Nothing to show for this reference.</p>';
}
function buildUrl(k){
  var i=k.indexOf(':');var t=k.slice(0,i),v=k.slice(i+1);
  return '/doc?'+t+'='+encodeURIComponent(v);
}
function renderIndex(){
  document.title='HARZ Reader \u2014 saved readings';
  document.getElementById('t').textContent='Saved readings';
  setBadge('CACHED');
  document.getElementById('meta').textContent='Documents stored on this device \u2014 readable with no internet.';
  var body=document.getElementById('body');
  dbp.then(function(db){return new Promise(function(res,rej){
    var t=db.transaction('docs','readonly').objectStore('docs');
    var out=[];
    var c=t.openCursor();
    c.onsuccess=function(){var cur=c.result;if(cur){out.push([cur.key,cur.value]);cur.continue()}else{res(out)}};
    c.onerror=function(){rej(c.error)};
  })}).then(function(rows){
    if(!rows.length){body.innerHTML='<p>No readings saved on this device yet. Open a document online once, then it can be read in flight mode.</p>';return}
    rows.sort(function(a,b){return (b[1].savedAt||0)-(a[1].savedAt||0)});
    var html='';
    for(var i=0;i<rows.length;i++){
      var k=rows[i][0],v=rows[i][1]||{};
      var title=(v.doc&&v.doc.title)?v.doc.title:k;
      var when=v.savedAt?new Date(v.savedAt).toLocaleString():'';
      html+='<p><a href="'+buildUrl(k)+'" style="color:#1877f2;text-decoration:none;font-weight:600">'+esc(title)+'</a><br><span class="note">'+esc(k)+' \u00B7 saved '+esc(when)+'</span></p>';
    }
    body.innerHTML=html;
  }).catch(function(){body.innerHTML='<p>Storage unavailable on this device.</p>'});
}
function main(){
  renderShellDone=true;
  if(!sid&&!id&&!hash){renderIndex();return;}
  getCache(refKey).then(function(cached){
    var p=new URLSearchParams();
    if(sid)p.set('sid',sid);if(id)p.set('id',id);if(hash)p.set('hash',hash);
    fetch('/doc-data?'+p.toString(),{cache:'no-store'}).then(function(r){
      if(!r.ok){netBar(false);if(cached){render(cached,'OFFLINE',cached.savedAt);netBar(false)}else{renderEmpty()}return}
      return r.json().then(function(j){
        netBar(true);
        if(!j.ok){if(cached){render(cached,'CACHED',cached.savedAt)}else{renderEmpty()}return}
        if(j.full){putCache(refKey,{ok:true,full:true,doc:j.doc,savedAt:Date.now()});try{if(navigator.serviceWorker&&navigator.serviceWorker.controller)navigator.serviceWorker.controller.postMessage({type:'add-saved',url:location.href})}catch(e3){}render(j,'LIVE',Date.now());}
        else{putCache(refKey,{ok:true,full:false,doc:j.doc,savedAt:Date.now()});render(j,'PREVIEW',Date.now());}
      });
    }).catch(function(e){
      netBar(false);
      if(cached){render(cached,'OFFLINE',cached.savedAt)}
      else{document.getElementById('t').textContent='Offline and not yet saved';setBadge('NO-NET');
        document.getElementById('meta').textContent='No internet and no stored copy of this document on this device.';
        document.getElementById('body').innerHTML='<p>Connect once to save this document, then it can be read in flight mode.</p>';}
    });
  });
}
var renderShellDone=false;
netBar(navigator.onLine);
main();
})();
</script></body></html>`;
      return new Response(H, { headers: { "Content-Type": "text/html; charset=utf-8", "Cache-Control": "no-store" } });
    }
    if (url.pathname === "/own") { return new Response(null,{status:204,headers:{"Cache-Control":"no-store"}}); }
    if (url.pathname === "/gather") {
      const d = (url.searchParams.get("d") || "").trim().toLowerCase().replace(/^https?:\/\//, "").replace(/\/.*$/, "");
      const CORS = { "Access-Control-Allow-Origin": "*" };
      if (!d) {
        try {
          const r = await fetch("https://harz-offline-browser.hamzarabiu390.workers.dev/gather");
          return new Response(r.body, { status: r.status, headers: { "Content-Type": "application/json", "Access-Control-Allow-Origin": "*", "Cache-Control": "no-store" } });
        } catch (err) {
          return Response.json({ ok: false, error: "library unreachable" }, { status: 502, headers: CORS });
        }
      }
      if (!/^[a-z0-9][a-z0-9.-]*\.[a-z]{2,}$/.test(d) || d.length > 100)
        return Response.json({ ok: false, error: "invalid domain" }, { status: 400, headers: CORS });
      try {
        const r = await fetch("https://harz-offline-browser.hamzarabiu390.workers.dev/gather?d=" + encodeURIComponent(d) + "&origin=harz-browser");
        return new Response(r.body, { status: r.status, headers: { "Content-Type": "application/json", "Access-Control-Allow-Origin": "*", "Cache-Control": "no-store" } });
      } catch (err) {
        return Response.json({ ok: false, error: "library unreachable" }, { status: 502, headers: CORS });
      }
    }
    if (url.pathname === "/page") {
      const target = url.searchParams.get("url") || "";
      if (!/^https?:\/\//i.test(target)) return new Response("bad url", { status: 400 });
      let r;
      try {
        let tu = null; try { tu = new URL(target); } catch (e) {}
        const ownM = tu && /^([a-z0-9-]+)\.harz\.workers\.dev$/.exec(tu.hostname);
        const bindKey = ownM ? "B_" + ownM[1].replace(/-/g, "_").toUpperCase() : null;
        if (bindKey && env[bindKey] && typeof env[bindKey].fetch === "function") {
          r = await env[bindKey].fetch(new Request(target, { headers: { "User-Agent": "Mozilla/5.0 (Linux; Android 10; Infinix XOS) AppleWebKit/537.36 Chrome/124.0.0.0 Mobile Safari/537.36", "Accept": "text/html,application/xhtml+xml,*/*" }, redirect: "manual" }));
          if (r.status >= 300 && r.status < 400 && r.headers.get("location")) {
            const loc = new URL(r.headers.get("location"), target).toString();
            return new Response(null, { status: 302, headers: { "Location": "/page?url=" + encodeURIComponent(loc), "Cache-Control": "no-store" } });
          }
        } else
        r = await fetch(target, {
          headers: {
            "User-Agent": "Mozilla/5.0 (Linux; Android 10; Infinix XOS) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Mobile Safari/537.36",
            "Accept": "text/html,application/xhtml+xml,*/*"
          },
          redirect: "follow"
        });
      } catch (err) {
        return new Response("upstream fetch failed", { status: 502 });
      }
      const finalUrl = r.url || target;
      const ct = r.headers.get("content-type") || "";
      if (!ct.includes("html")) {
        return new Response(r.body, { status: r.status, headers: {
          "Content-Type": ct || "application/octet-stream",
          "Content-Security-Policy": "sandbox",
          "Cache-Control": "no-store"
        } });
      }
      let body = await r.text();
      const jsUrl = finalUrl.replace(/\\/g, "\\\\").replace(/'/g, "\\'");
      const inj = '<base href="' + finalUrl.replace(/"/g, "&quot;") + '">' +
        '<script>document.addEventListener("click",function(e){var t=e.target;var a=t&&t.closest?t.closest("a[href]"):null;if(a){e.preventDefault();parent.postMessage({harzNav:a.href},"*");}},true);' +
        'setTimeout(function(){try{parent.postMessage({harzTitle:document.title,harzUrl:"' + jsUrl + '"},"*");}catch(e){}},300);<' + '/script>';
      if (/<head[^>]*>/i.test(body)) {
        body = body.replace(/<head[^>]*>/i, m => m + inj);
      } else {
        body = inj + body;
      }
      return new Response(body, { status: r.ok ? 200 : 502, headers: {
        "Content-Type": "text/html; charset=utf-8",
        "Content-Security-Policy": "sandbox allow-scripts allow-forms allow-popups",
        "X-Content-Type-Options": "nosniff",
        "Cache-Control": "no-store"
      } });
    }

    const html = b64ToUtf8("");

    return new Response(html, {
      headers: {
        "Content-Type": "text/html; charset=utf-8",
        "Cache-Control": "no-cache, must-revalidate",
        "Access-Control-Allow-Origin": "*"
      }
    });
  }
};
